scene.fog = new THREE.FogExp2(0xd6e4f0, 0.012);

renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.12;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;

const keyLight = new THREE.DirectionalLight(0xfff5e6, 1.45);
keyLight.position.set(35, 60, 25);
keyLight.castShadow = true;
keyLight.shadow.mapSize.set(2048, 2048);
keyLight.shadow.camera.near = 0.5;
keyLight.shadow.camera.far = 300;
keyLight.shadow.camera.left = -120;
keyLight.shadow.camera.right = 120;
keyLight.shadow.camera.top = 120;
keyLight.shadow.camera.bottom = -120;
keyLight.shadow.bias = -0.0005;

const fillLight = new THREE.DirectionalLight(0xc9e6ff, 0.6);
fillLight.position.set(-40, 25, 40);

const rimLight = new THREE.PointLight(0x00d4ff, 0.85, 140);
rimLight.position.set(0, 70, -50);

const ambientLight = new THREE.AmbientLight(0x8fa3bf, 0.38);

scene.add(keyLight, fillLight, rimLight, ambientLight);

const cityGroup = new THREE.Group();
scene.add(cityGroup);

const concreteMat = new THREE.MeshStandardMaterial({
  color: 0xe8eef5,
  roughness: 0.75,
  metalness: 0.08
});

const glassMat = new THREE.MeshStandardMaterial({
  color: 0x2c3e50,
  roughness: 0.15,
  metalness: 0.95,
  transparent: true,
  opacity: 0.85
});

const glowMat = new THREE.MeshBasicMaterial({
  color: 0xffdd88,
  side: THREE.DoubleSide
});

const foundationGeo = new THREE.BoxGeometry(1, 1, 1);
const foundationMesh = new THREE.InstancedMesh(foundationGeo, concreteMat, 1000);
foundationMesh.castShadow = true;
foundationMesh.receiveShadow = true;

const towerGeo = new THREE.BoxGeometry(1, 1, 1);
const towerMesh = new THREE.InstancedMesh(towerGeo, glassMat, 1500);
towerMesh.castShadow = true;
towerMesh.receiveShadow = true;

const spireGeo = new THREE.CylinderGeometry(0.08, 0.25, 1, 8);
const spireMat = new THREE.MeshStandardMaterial({ color: 0xf5f7fa, roughness: 0.35, metalness: 0.75 });
const spireMesh = new THREE.InstancedMesh(spireGeo, spireMat, 800);

const dummy = new THREE.Object3D();
const _color = new THREE.Color();

let idx = 0;
for (let x = -60; x < 60; x += 5) {
  for (let z = -60; z < 60; z += 5) {
    if (Math.random() > 0.65) continue;
    const h = Math.random() * 20 + 8;
    dummy.position.set(x * 2.2 + (Math.random() - 0.5), h / 2, z * 2.2 + (Math.random() - 0.5));
    dummy.scale.set(Math.random() * 4 + 4, h, Math.random() * 4 + 4);
    dummy.updateMatrix();
    foundationMesh.setMatrixAt(idx, dummy.matrix);
    _color.setHSL(0.6, 0.06, 0.72 + Math.random() * 0.18);
    foundationMesh.setColorAt(idx, _color);
    idx++;
  }
}
foundationMesh.count = idx;
cityGroup.add(foundationMesh);

idx = 0;
for (let i = 0; i < 1500; i++) {
  const x = (Math.random() - 0.5) * 200;
  const z = (Math.random() - 0.5) * 200;
  const h = Math.pow(Math.random(), 2) * 90 + 15;
  dummy.position.set(x, h / 2 + 12, z);
  dummy.scale.set(Math.random() * 5 + 3, h, Math.random() * 5 + 3);
  dummy.updateMatrix();
  towerMesh.setMatrixAt(idx, dummy.matrix);
  _color.setHSL(0.58, 0.25, 0.18 + Math.random() * 0.25);
  towerMesh.setColorAt(idx, _color);
  idx++;
}
towerMesh.count = idx;
cityGroup.add(towerMesh);

idx = 0;
for (let i = 0; i < 800; i++) {
  const x = (Math.random() - 0.5) * 180;
  const z = (Math.random() - 0.5) * 180;
  const h = Math.random() * 30 + 8;
  dummy.position.set(x, 70 + Math.random() * 25, z);
  dummy.scale.set(1, h, 1);
  dummy.updateMatrix();
  spireMesh.setMatrixAt(idx, dummy.matrix);
  idx++;
}
spireMesh.count = idx;
cityGroup.add(spireMesh);

const windowGeo = new THREE.PlaneGeometry(0.8, 0.8);
const windowMesh = new THREE.InstancedMesh(windowGeo, glowMat, 4000);
let wIdx = 0;
for (let i = 0; i < 4000; i++) {
  const x = (Math.random() - 0.5) * 220;
  const z = (Math.random() - 0.5) * 220;
  const y = Math.random() * 80 + 10;
  dummy.position.set(x, y, z);
  dummy.rotation.y = Math.random() * Math.PI * 2;
  dummy.updateMatrix();
  windowMesh.setMatrixAt(wIdx++, dummy.matrix);
}
windowMesh.count = wIdx;
cityGroup.add(windowMesh);

const trafficGeo = new THREE.ConeGeometry(0.25, 0.9, 6);
const trafficMat = new THREE.MeshStandardMaterial({
  color: 0xff2200,
  emissive: 0xff4400,
  emissiveIntensity: 2.5,
  roughness: 0.3
});
const trafficCount = 100;
const trafficMesh = new THREE.InstancedMesh(trafficGeo, trafficMat, trafficCount);
const trafficData = [];

for (let i = 0; i < trafficCount; i++) {
  trafficData.push({
    x: (Math.random() - 0.5) * 240,
    y: Math.random() * 30 + 20,
    z: (Math.random() - 0.5) * 240,
    speed: (Math.random() * 0.4 + 0.25) * (Math.random() > 0.5 ? 1 : -1),
    bobOffset: Math.random() * 100
  });
}
scene.add(trafficMesh);

const holoGeo = new THREE.PlaneGeometry(5, 8);
const holoMat = new THREE.MeshBasicMaterial({
  color: 0x00ffff,
  side: THREE.DoubleSide,
  transparent: true,
  opacity: 0.5,
  blending: THREE.AdditiveBlending
});
const holoMesh = new THREE.InstancedMesh(holoGeo, holoMat, 24);
for (let i = 0; i < 24; i++) {
  dummy.position.set(
    (Math.random() - 0.5) * 120,
    Math.random() * 50 + 25,
    (Math.random() - 0.5) * 120
  );
  dummy.rotation.y = Math.random() * Math.PI;
  dummy.updateMatrix();
  holoMesh.setMatrixAt(i, dummy.matrix);
}
cityGroup.add(holoMesh);

camera.position.set(80, 50, 80);
camera.lookAt(0, 25, 0);

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.05;
controls.autoRotate = true;
controls.autoRotateSpeed = 0.25;
controls.maxPolarAngle = Math.PI / 2 - 0.02;
controls.minDistance = 15;
controls.maxDistance = 200;
controls.target.set(0, 25, 0);

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  const td = new THREE.Object3D();
  for (let i = 0; i < trafficCount; i++) {
    const data = trafficData[i];
    data.x += data.speed;
    if (data.x > 120) data.x = -120;
    if (data.x < -120) data.x = 120;

    td.position.set(data.x, data.y + Math.sin(t * 2 + data.bobOffset) * 1.5, data.z);
    td.rotation.z = data.speed > 0 ? -Math.PI / 2 : Math.PI / 2;
    td.rotation.x = Math.sin(t * 3 + data.bobOffset) * 0.08;
    td.updateMatrix();
    trafficMesh.setMatrixAt(i, td.matrix);
  }
  trafficMesh.instanceMatrix.needsUpdate = true;

  holoMat.opacity = 0.35 + Math.sin(t * 1.8) * 0.15;
  glowMat.color.setHSL(0.12, 0.9, 0.55 + Math.sin(t * 0.4) * 0.15);

  rimLight.position.x = Math.sin(t * 0.15) * 30;
  rimLight.intensity = 0.85 + Math.sin(t * 1.2) * 0.15;

  controls.update();
  renderer.render(scene, camera);
}
animate();

